"""A short project narrative; full technical and media references remain optional."""
from components import *
from media import video_gallery, resources, full_screen_gallery, promo_gallery, linkedin_series


def collabrium_page():
    overview = '''<p>Collabrium is a four-person graduation project for organizations managing projects, people, learning and internal collaboration. The challenge was to connect those features around the same users, teams and organization context.</p><p>A person’s organization, role, project membership and account state influence what they can see and do. That context follows the work from planning through delivery, reporting and notifications.</p><div class="pf-case-intro"><p><strong>Team context.</strong> I served as Team Lead &amp; Backend Developer alongside Abeer, Hanan and Nada, under Dr. Thaer Sammar’s supervision at PTUK. The platform capabilities describe our shared implementation.</p></div>'''
    contribution = f'''<p>I led requirements analysis and two-week Agile sprints, and contributed to backend implementation and React/API integration. These are three specific areas of my backend work:</p><ul class="pf-contributions">
    <li><h3>Work-item rules and lifecycle behavior</h3><p>I contributed relationship rules and status checks for work items. User Story release and completion inspect linked tasks, bugs and test outcomes.</p>{ext(C+'Domain/Models/UserStory.cs','Explore the domain implementation','text-link')}</li>
    <li><h3>Tenant-aware request handling</h3><p>I worked on the middleware that resolves the user’s organization, checks activation and membership, and establishes request context.</p>{ext(C+'API/Middlewares/TentantMiddleware.cs','Explore the tenant middleware','text-link')}</li>
    <li><h3>Connected sprint and reporting workflows</h3><p>I contributed sprint completion and analytical queries. Unfinished work returns to the backlog while completed work retains its sprint history.</p>{ext(C+'Application/Features/Sprints/Commands/CompleteSprint.cs','Explore sprint completion','text-link')}{ext(C+'Infrastructure/Persistence/ReadModels/ReportsReadModel.cs','Explore the report queries','text-link')}</li>
    </ul>'''
    decisions = '<p>Three shared-backend decisions illustrate how the features work together. Each leads to the implementation.</p>'
    decisions += decision(1, 'Access follows the organization and the resource.', 'Tenant middleware establishes organization membership for ordinary tenant-aware HTTP requests. Project authorization then checks the specific project. The two boundaries answer different access questions.', C+'Infrastructure/Security/AuthRequirements/MustHaveProjectAccess.cs')
    decisions += decision(2, 'Completion reflects the work underneath it.', 'A User Story cannot simply be marked complete without checking its linked tasks, bugs and test outcomes. The domain model owns that rule rather than leaving it to a screen.', C+'Domain/Models/UserStory.cs')
    decisions += decision(3, 'Related writes share a commit boundary.', 'Work-item creation coordinates the item, its generated project code and history in a database transaction. Email and SignalR delivery happen across a separate boundary; the transaction does not guarantee their delivery.', C+'Application/Features/WorkItems/Commands/CreateWorkItem.cs')
    decisions += '<a class="text-link" href="collabrium-engineering.html#code-skills">Explore the C# examples and full decision notes '+arrow('right')+'</a>'
    demo = '<p>Watch the project board and work-item delivery workflow. The recording shows the graduation-project interface; use full screen to inspect the details.</p>'+video_gallery('case', [0])
    demo += '<details class="pf-resource-disclosure"><summary>Four more recordings: organization, reports, learning and tenant architecture</summary>'+video_gallery('case-extra', [1,2,3,4])+'</details>'
    architecture = f'''<p>The backend has four projects: API, Application, Domain and Infrastructure. The API handles HTTP contracts, application handlers coordinate use cases, domain models enforce behavior, and infrastructure implements persistence and external services.</p><div class="architecture-diagram">{ARCHITECTURE}</div><p>Commands apply domain behavior and commit related writes. Purpose-specific query models return DTOs for screens and reports. Both paths use SQL Server; this CQRS implementation does not require separate databases.</p><div id="backend-engineering" class="pf-status-note"><strong>For a technical review</strong><p>The full reference covers the 13 functional areas, six workflows, access model, persistence, SignalR, email, workers, AI and reporting.</p><a class="text-link" href="collabrium-engineering.html">Open the backend reference {arrow('right')}</a></div>'''
    reflection = '''<p>Collabrium taught me to reason about connected behavior: a sprint change can affect relationships, history, reports and notifications. Clear boundaries make those connections easier to explain and maintain.</p><div class="pf-status-note"><strong>Current verification and next steps</strong><p>The reviewed graduation-project snapshot has no automated unit/integration test project or deployment pipeline. My next steps are domain-transition tests, tenant/project authorization integration tests, request tracing and more reliable external notification delivery.</p></div>'''
    sources = '<div class="source-grid">'+ext(GITHUB+'/Collabrium','Backend repository')+ext('https://github.com/NadaAsadk/Collabrium-Frontend-Showcase','Team frontend showcase')+'<a href="collabrium-engineering.html">Backend architecture &amp; code '+arrow()+'</a><a href="presentation.html">Project summary &amp; presentation '+arrow()+'</a></div>'
    sources += '<details class="pf-resource-disclosure" id="walkthrough"><summary>Application screenshots, grouped by workflow</summary>'+full_screen_gallery()+'</details>'
    sources += '<details class="pf-resource-disclosure" id="project-story"><summary>Original team and project overview visuals</summary>'+promo_gallery('case')+'</details>'
    sources += '<details class="pf-resource-disclosure" id="documentation"><summary>Thesis and full graduation presentation</summary><p>Optional project references: the 272-page thesis and the 53-slide presentation with embedded recordings. A lightweight project summary is available before the full download.</p>'+resources()+'</details>'
    sources += '<details class="pf-resource-disclosure"><summary>Project development posts on LinkedIn</summary>'+linkedin_series()+'</details>'
    return case_page('collabrium','Collabrium','Graduation project · Four-person team',
        'A connected workspace for projects, people and learning.',
        'A .NET backend connecting an organization’s project delivery, teams, learning, community and reporting.',
        'Team Lead &amp; Backend Developer','Oct 2025 — Jun 2026','Academic team project · PTUK',
        ['C# / .NET 8','ASP.NET Core','EF Core / SQL Server','CQRS / MediatR','Identity / JWT','SignalR'],
        '', '', [('overview','Project & team context',overview),('contribution','My contribution',contribution),
        ('decisions','Three engineering decisions',decisions),('demo','Recorded workflow',demo),
        ('architecture','Architecture overview',architecture),('reflection','Lessons & next steps',reflection),
        ('sources','Code & optional resources',sources)],'hotel-booking','Hotel Booking API')
